WITH metrics AS (SELECT id, supplier_name, country, city, rating, SUM(rating) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating, LAG(rating, 2) OVER (ORDER BY rating, id) AS prev_rating, FIRST_VALUE(rating) IGNORE NULLS OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_rating FROM suppliers WHERE city IN ('Berlin', 'Singapore')) SELECT CASE WHEN prev_rating >= 4.2 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_rating_tier, city, country, COUNT(DISTINCT city) AS distinct_cities, SUM(CASE WHEN country = 'DE' THEN cumulative_rating ELSE 0 END) AS de_cumulative_rating, SUM(CASE WHEN city = 'Chiang Mai' THEN cumulative_rating ELSE 0 END) AS chiang_mai_cumulative_rating FROM metrics GROUP BY CASE WHEN prev_rating >= 4.2 THEN 'PREMIUM' ELSE 'STANDARD' END, city, country
